# Generated by manage.py generate_test_cases.
import json
from unittest.mock import patch

from django.contrib.contenttypes.models import ContentType
from django.http import HttpResponse
from django.urls import reverse

from bloomerp.models.communication.calendar import CalendarEvent
from bloomerp.models.definition import DataviewAction
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestConfiguredDataviewActionComponent(BloomerpComponentTestCase):
    """Tests function `configured_dataview_action` from `bloomerp/components/objects/dataviews/dataview_action.py`."""

    view_name = 'components_dataview_action'

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Exercise Inbox navigation and configurable toolbar targets through real endpoints."""
        return [
            RequestScenario(
                name="Back to Inbox navigates through an HTMX GET",
                method="GET",
                user=self.admin_user,
                prepare=self.prepare_calendar_action,
                query_params={"inboxes": "1"},
                expected=ExpectedResult(
                    response_validators=[
                        self.opens_inbox,
                        self.header_equals("HX-Retarget", "#main-content"),
                    ]
                ),
            ),
            RequestScenario(
                name="Toolbar renders the target and escaped custom attributes",
                view_name="components_dataview",
                user=self.admin_user,
                prepare=self.prepare_custom_toolbar,
                query_params={"inboxes": "1"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text('hx-target="#main-content"'),
                        self.contains_text('title="A &quot;quoted&quot; title"'),
                        self.contains_text('data-navigation="inbox"'),
                        self.contains_text('hx-get="'),
                    ]
                ),
            ),
            RequestScenario(
                name="Back to Inbox is absent from the general calendar toolbar",
                view_name="components_dataview",
                user=self.admin_user,
                prepare=self.prepare_custom_toolbar,
                expected=ExpectedResult(response_validators=[
                    self.does_not_contain_text('data-data-view-button="back_to_inbox"'),
                ]),
            ),
            RequestScenario(
                name="Unscoped Back to Inbox execution is denied",
                user=self.admin_user,
                prepare=self.prepare_calendar_action,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="GET navigation rejects POST execution",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_calendar_action,
                query_params={"inboxes": "1"},
                expected=ExpectedResult(status_code=405, response_validators=[
                    self.header_equals("Allow", "GET"),
                ]),
            ),
            RequestScenario(
                name="POST actions render CSRF tokens",
                view_name="components_dataview",
                user=self.admin_user,
                prepare=self.prepare_post_toolbar,
                query_params={"inboxes": "1"},
                expected=ExpectedResult(response_validators=[
                    self.contains_text('hx-post="'),
                    self.contains_text('csrfmiddlewaretoken'),
                ]),
            ),
            RequestScenario(
                name="POST actions reject GET execution",
                user=self.admin_user,
                prepare=self.prepare_post_action,
                query_params={"inboxes": "1"},
                expected=ExpectedResult(status_code=405, response_validators=[
                    self.header_equals("Allow", "POST"),
                ]),
            ),
        ]

    def prepare_post_toolbar(self, scenario: RequestScenario) -> None:
        """Render a POST action using the existing navigation callback as a harmless fixture."""
        self.prepare_custom_toolbar(scenario)
        settings = CalendarEvent.bloomerp_config.model_view_settings
        actions = [
            action.model_copy(update={"method": "POST"})
            if isinstance(action, DataviewAction) else action
            for action in settings.dataview_actions
        ]
        self.enterContext(patch.object(settings, "dataview_actions", actions))

    def prepare_post_action(self, scenario: RequestScenario) -> None:
        """Resolve a POST-only action to verify method enforcement at execution time."""
        self.prepare_post_toolbar(scenario)
        self.prepare_calendar_action(scenario)

    def prepare_calendar_action(self, scenario: RequestScenario) -> None:
        """Resolve the real calendar action without creating or modifying an event."""
        scenario.view_kwargs = {
            "content_type_id": ContentType.objects.get_for_model(CalendarEvent).pk,
            "action_id": "back_to_inbox",
        }

    def prepare_custom_toolbar(self, scenario: RequestScenario) -> None:
        """Temporarily configure attributes on the real Back to Inbox toolbar action."""
        scenario.view_kwargs = {
            "content_type_id": ContentType.objects.get_for_model(CalendarEvent).pk,
        }
        settings = CalendarEvent.bloomerp_config.model_view_settings
        actions = [
            action.model_copy(update={
                "button_attrs": {
                    "title": 'A "quoted" title',
                    "data-navigation": "inbox",
                }
            }) if isinstance(action, DataviewAction) else action
            for action in settings.dataview_actions
        ]
        self.enterContext(patch.object(settings, "dataview_actions", actions))

    def opens_inbox(self, response: HttpResponse) -> bool:
        """Require navigation to the Inbox page inside the main content panel."""
        location = json.loads(response.headers["HX-Location"])
        return location["path"] == reverse("inbox") and location["target"] == "#main-content"
